function calcular(datos) {
  var dia = function (iso) { return new Date(Date.parse(iso) - 5 * 3600 * 1000).toISOString().slice(0, 10); };
  var N = 365;
  var pedidos = (datos.tablas && datos.tablas.pedidos) || [];
  var validos = { confirmado: true, enviado: true, entregado: true, novedad: true };
  var etiquetas = [];
  var i;
  for (i = N - 1; i >= 0; i--) {
    var iso = new Date(Date.parse(datos.hoy) - i * 86400000).toISOString();
    etiquetas.push(dia(iso));
  }
  var conteo = {};
  for (i = 0; i < etiquetas.length; i++) { conteo[etiquetas[i]] = 0; }
  for (i = 0; i < pedidos.length; i++) {
    var p = pedidos[i];
    if (!p || !validos[p.estado] || !p.creado) { continue; }
    var d = dia(p.creado);
    if (d in conteo) { conteo[d] += 1; }
  }
  var serie = [];
  var total = 0;
  for (i = 0; i < etiquetas.length; i++) {
    var v = conteo[etiquetas[i]];
    total += v;
    serie.push({ etiqueta: etiquetas[i], valor: v });
  }
  return { valor: total, unidad: "pedidos", serie: serie, nota: "Cuenta pedidos confirmados, enviados, entregados y con novedad por dia de creacion (hora Bogota) en los ultimos 365 dias." };
}

