function calcular(datos) {
  var N = 60;
  var dia = function (iso) { return new Date(Date.parse(iso) - 5 * 3600 * 1000).toISOString().slice(0, 10); };
  var hoyDia = dia(datos.hoy);
  var corte = dia(new Date(Date.parse(datos.hoy) - N * 86400000).toISOString());
  var pedidos = (datos.tablas && datos.tablas.pedidos) || [];
  var esVenta = function (e) { return e === 'confirmado' || e === 'enviado' || e === 'entregado' || e === 'novedad'; };
  var conteo = {};
  for (var i = 0; i < pedidos.length; i++) {
    var p = pedidos[i];
    if (!esVenta(p.estado)) continue;
    if (!p.creado) continue;
    var d = dia(p.creado);
    if (!(d > corte && d <= hoyDia)) continue;
    var c = p.clienteId;
    if (!c) continue;
    conteo[c] = (conteo[c] || 0) + 1;
  }
  var total = 0;
  var repiten = 0;
  for (var k in conteo) {
    if (Object.prototype.hasOwnProperty.call(conteo, k)) {
      total++;
      if (conteo[k] > 1) repiten++;
    }
  }
  var pct = total === 0 ? 0 : (repiten * 100 / total);
  var valor = Math.round(pct * 10) / 10;
  return {
    valor: valor,
    unidad: '%',
    nota: 'De ' + total + ' clientes con venta confirmada, enviada, entregada o con novedad en los últimos 60 días, ' + repiten + ' compraron más de una vez.'
  };
}

