function consultar(datos) {
  var dia = function (iso) {
    return new Date(Date.parse(iso) - 5 * 3600 * 1000).toISOString().slice(0, 10);
  };
  var tablas = (datos && datos.tablas) || {};
  var pedidos = tablas.pedidos || [];
  var clientes = tablas.clientes || [];
  var limite = dia(new Date(Date.parse(datos.hoy) - 365 * 86400000).toISOString());
  var esVenta = function (e) {
    return e === "confirmado" || e === "enviado" || e === "entregado" || e === "novedad";
  };
  var nombres = {};
  for (var i = 0; i < clientes.length; i++) {
    var c = clientes[i];
    if (c && c.id) nombres[c.id] = c.nombre || c.id;
  }
  var acum = {};
  for (var j = 0; j < pedidos.length; j++) {
    var p = pedidos[j];
    if (!p || !p.clienteId) continue;
    if (!esVenta(p.estado)) continue;
    if (!p.creado) continue;
    var d = "";
    try { d = dia(p.creado); } catch (e) { continue; }
    if (!(d > limite)) continue;
    var t = typeof p.total === "number" ? p.total : parseInt(p.total, 10);
    if (isNaN(t)) t = 0;
    if (!acum[p.clienteId]) acum[p.clienteId] = { clienteId: p.clienteId, total: 0, pedidos: 0 };
    acum[p.clienteId].total += t;
    acum[p.clienteId].pedidos += 1;
  }
  var lista = [];
  for (var k in acum) {
    if (Object.prototype.hasOwnProperty.call(acum, k)) lista.push(acum[k]);
  }
  lista.sort(function (a, b) {
    if (b.total !== a.total) return b.total - a.total;
    return b.pedidos - a.pedidos;
  });
  var top = lista.slice(0, 10);
  var filas = [];
  for (var n = 0; n < top.length; n++) {
    var r = top[n];
    var nombre = nombres[r.clienteId] || r.clienteId;
    var promedio = r.pedidos > 0 ? Math.round(r.total / r.pedidos) : 0;
    filas.push({
      posicion: n + 1,
      cliente: String(nombre),
      pedidos: r.pedidos,
      ticket_promedio: promedio,
      total_comprado: r.total
    });
  }
  return filas;
}

