function calcular(datos) {
  var dia = function (iso) { return new Date(Date.parse(iso) - 5 * 3600 * 1000).toISOString().slice(0, 10); };
  var N = 365;
  var hoyDia = dia(datos.hoy);
  var umbral = dia(new Date(Date.parse(datos.hoy) - N * 86400000).toISOString());
  var pedidos = (datos.tablas && datos.tablas.pedidos) || [];
  var productos = (datos.tablas && datos.tablas.productos) || [];
  var nombresPorId = {};
  for (var i = 0; i < productos.length; i++) {
    if (productos[i] && productos[i].id) nombresPorId[productos[i].id] = productos[i].nombre;
  }
  function esVenta(e) { return e === 'confirmado' || e === 'enviado' || e === 'entregado' || e === 'novedad'; }
  var porProducto = {};
  var total = 0;
  for (var j = 0; j < pedidos.length; j++) {
    var p = pedidos[j];
    if (!p || !esVenta(p.estado)) continue;
    if (!p.creado) continue;
    var d = dia(p.creado);
    if (!(d > umbral && d <= hoyDia)) continue;
    var items = p.items || [];
    for (var k = 0; k < items.length; k++) {
      var it = items[k];
      if (!it) continue;
      var cant = Number(it.cantidad) || 0;
      if (cant <= 0) continue;
      var etiqueta = it.nombre || nombresPorId[it.productoId] || String(it.productoId || 'Sin nombre');
      if (it.productoId && nombresPorId[it.productoId]) etiqueta = nombresPorId[it.productoId];
      porProducto[etiqueta] = (porProducto[etiqueta] || 0) + cant;
      total += cant;
    }
  }
  var serie = Object.keys(porProducto).map(function (etiqueta) {
    return { etiqueta: etiqueta, valor: porProducto[etiqueta] };
  });
  serie.sort(function (a, b) { return b.valor - a.valor; });
  return {
    valor: total,
    unidad: 'unidades',
    serie: serie,
    nota: 'Unidades vendidas en los últimos 365 días en pedidos confirmados, enviados, entregados y con novedad.'
  };
}

