  var corte = dia(new Date(Date.parse(datos.hoy) - N * 86400000).toISOString());
  var grupos = {};
  for (var i = 0; i < mensajes.length; i++) {
    var m = mensajes[i];
    if (!m || !m.clienteId || !m.creado) continue;
    var t = Date.parse(m.creado);
    if (isNaN(t)) continue;
    var d = dia(m.creado);
    if (!(d > corte && d <= diaHoy)) continue;
    var k = m.clienteId + "|" + d;
    if (!grupos[k]) grupos[k] = [];
    grupos[k].push({ rol: m.rol, t: t });
  }
  var tiempos = [];
  var totalConv = 0;
  for (var key in grupos) {
    var arr = grupos[key];
    arr.sort(function (a, b) { return a.t - b.t; });
    var tCliente = null;
    for (var j = 0; j < arr.length; j++) {
      if (arr[j].rol === "cliente") { tCliente = arr[j].t; break; }
    }
    if (tCliente === null) continue;
    totalConv++;
    var tAgente = null;
    for (var k2 = 0; k2 < arr.length; k2++) {
      if (arr[k2].rol === "agente" && arr[k2].t > tCliente) { tAgente = arr[k2].t; break; }
    }
    if (tAgente === null) continue;
    var seg = Math.round((tAgente - tCliente) / 1000);
    if (seg >= 0) tiempos.push(seg);
  }
  tiempos.sort(function (a, b) { return a - b; });
  var n = tiempos.length;
  var mediana = null;
  var p90 = null;
  var minimo = null;
  var maximo = null;
  if (n > 0) {
    minimo = tiempos[0];
    maximo = tiempos[n - 1];
    if (n % 2 === 1) {
      mediana = tiempos[(n - 1) / 2];
    } else {
      mediana = Math.round((tiempos[n / 2 - 1] + tiempos[n / 2]) / 2);
    }
    var idx = Math.ceil(0.9 * n) - 1;
    if (idx < 0) idx = 0;
    if (idx >= n) idx = n - 1;
    p90 = tiempos[idx];
  }
  var inicioDia = "";
  // dia siguiente al corte: buscar sumando 1 dia al corte aproximado usando datos.hoy como base es complejo, lo derivamos del rango:
  // inicio = dia(corte 00:00 Bogota + 24h). Aproximacion: corte + 1 dia calendario.
  function sumarUnDia(yyyyMmDd) {
    var p = yyyyMmDd.split("-");
    var ms = Date.UTC(parseInt(p[0], 10), parseInt(p[1], 10) - 1, parseInt(p[2], 10)) + 86400000;
    return new Date(ms).toISOString().slice(0, 10);
  }
