    p90_segundos: p90,
    minimo_segundos: minimo,
    maximo_segundos: maximo,
    nota: n === 0 ? "Sin conversaciones con respuesta en los ultimos 30 dias." : "P90 con rango mas cercano (ceil 0.9*n). Solo conversaciones con respuesta del agente."
  }];
}

