function calcular(datos) {
  const dia = (iso) => new Date(Date.parse(iso) - 5 * 3600 * 1000).toISOString().slice(0, 10);
  const N = 30;
  const hoyDia = dia(datos.hoy);
  const limite = dia(new Date(Date.parse(datos.hoy) - N * 86400000).toISOString());
  const pedidos = (datos.tablas && datos.tablas.pedidos) || [];
  const porCiudad = {};
  let totGeneral = 0;
  let cancGeneral = 0;
  for (let i = 0; i < pedidos.length; i++) {
    const p = pedidos[i];
    if (!p || !p.creado) continue;
    const d = dia(p.creado);
    if (d <= limite || d > hoyDia) continue;
    const ciudad = p.ciudad || "Sin ciudad";
    if (!porCiudad[ciudad]) porCiudad[ciudad] = { total: 0, cancelados: 0 };
    porCiudad[ciudad].total += 1;
    totGeneral += 1;
    if (p.estado === "cancelado") {
      porCiudad[ciudad].cancelados += 1;
      cancGeneral += 1;
    }
  }
  const ciudades = Object.keys(porCiudad).sort();
  const serie = [];
  for (let j = 0; j < ciudades.length; j++) {
    const c = ciudades[j];
    const g = porCiudad[c];
    const porc = g.total === 0 ? 0 : Math.round((g.cancelados * 1000) / g.total) / 10;
    serie.push({ etiqueta: c, valor: porc });
  }
  const valor = totGeneral === 0 ? 0 : Math.round((cancGeneral * 1000) / totGeneral) / 10;
  return {
    valor: valor,
