  var casos = (datos.tablas && datos.tablas.casos) || [];
  var suma = 0;
  var n = 0;
  for (var i = 0; i < casos.length; i++) {
    var c = casos[i];
    if (!c || !c.creado || !c.resuelto) continue;
    if (c.estado !== 'resuelto') continue;
    var dCreado = dia(c.creado);
    if (!(dCreado > limite && dCreado <= hoyDia)) continue;
    var ms = Date.parse(c.resuelto) - Date.parse(c.creado);
    if (isNaN(ms) || ms < 0) continue;
    suma += ms / 3600000;
    n++;
  }
  var prom = n === 0 ? 0 : Math.round((suma / n) * 100) / 100;
  return { valor: prom, nota: 'Promedio de horas entre creado y resuelto de ' + n + ' casos resueltos creados en los últimos 365 días.' };
}

