function consultar(datos) {
  var dia = function (iso) {
    return new Date(Date.parse(iso) - 5 * 3600 * 1000).toISOString().slice(0, 10);
  };
  var fmtBogota = function (iso) {
    return new Date(Date.parse(iso) - 5 * 3600 * 1000).toISOString().slice(0, 16).replace("T", " ");
  };
  var tablas = (datos && datos.tablas) || {};
  var pedidos = tablas.pedidos || [];
  var clientes = tablas.clientes || [];
  var mapaClientes = {};
  for (var i = 0; i < clientes.length; i++) {
    var c = clientes[i];
    if (c && c.id) mapaClientes[c.id] = c.nombre || "Sin nombre";
  }
  var hoyMs = Date.parse(datos.hoy);
  var TRES_DIAS_MS = 3 * 86400000;
  var limiteDia = dia(new Date(hoyMs - 365 * 86400000).toISOString());
  var filas = [];
  for (var j = 0; j < pedidos.length; j++) {
    var p = pedidos[j];
    if (!p || p.estado !== "pendiente" || !p.creado) continue;
    var creadoMs = Date.parse(p.creado);
    if (isNaN(creadoMs)) continue;
    if (hoyMs - creadoMs <= TRES_DIAS_MS) continue;
    var diaPedido = dia(p.creado);
    if (!(diaPedido > limiteDia)) continue;
    var diasPend = Math.floor((hoyMs - creadoMs) / 86400000);
    filas.push({
      numero: p.numero != null ? p.numero : null,
      cliente: mapaClientes[p.clienteId] || "Sin nombre",
      ciudad: p.ciudad || "",
      total: typeof p.total === "number" ? p.total : 0,
      creada: fmtBogota(p.creado),
      dias_pendiente: diasPend,
      estado: p.estado,
      _ts: creadoMs
    });
  }
  filas.sort(function (a, b) { return b._ts - a._ts; });
  var out = [];
  var n = filas.length > 200 ? 200 : filas.length;
  for (var k = 0; k < n; k++) {
    out.push({
      numero: filas[k].numero,
      cliente: filas[k].cliente,
      ciudad: filas[k].ciudad,
      total: filas[k].total,
      creada: filas[k].creada,
      dias_pendiente: filas[k].dias_pendiente,
      estado: filas[k].estado
    });
  }
  return out;
}
